// D2 environment on the client (WP-09; D2-AC-15 client part; AWR-04 §6.3, §6.5, §7.3; ADR-102; 14 §20.5.4):
// golden parity of engine/environment/sky/*.ts and the optics additions with python/awr/environment (tests/environment/
// golden/d2_sky.json, generated by tests/environment/d2fix.py); EnvStore sky evaluation: calendar instant at tRender, sun
// from the keyframe or the local NOAA function with the world anchor, illuminance band, server humidity / surface /
// acoustic background; the summary's sky field; D1 frames (no D2 fields) keep the fixed sun and a null sky summary.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import {
  EnvStore, PRESETS_MODEL, SURFACE_CLASSES, aWeightDb, airTempC, bandLevelsDba, buildSummary, daylightK, derive, illumBand, illuminanceLx,
  kCrossOf, kimFactor, levelDba, newDerived, parseUtcMs, refractionDeg, sigmaLambda, sigmaWvPerM, skyTempC, solarPosition, surfaceTempC,
  totalDba, waterVapourGm3, type AcousticProfile, type EnvKeyframeWire,
} from '@/engine/environment'
import { formatLocal } from '@/engine/environment/sky/calendar'

type Case = { fn: string; args: Record<string, any>; out: Record<string, any> } // eslint-disable-line @typescript-eslint/no-explicit-any
const ROOT = new URL('../../../../', import.meta.url)
const gold = JSON.parse(readFileSync(new URL('tests/environment/golden/d2_sky.json', ROOT), 'utf8')) as { tolerance: { rtol: number; atol: number }; cases: Case[] }
const { rtol, atol } = gold.tolerance
const close = (a: number, b: number, k = 1): boolean => Math.abs(a - b) <= k * (atol + rtol * Math.abs(b))
const kV2 = PRESETS_MODEL.c.k_v2

/* eslint-disable @typescript-eslint/no-explicit-any */
const DISPATCH: Record<string, (a: any) => Record<string, any>> = {
  solar_position: (a) => {
    const p = solarPosition(a.unix_ms, a.lat_deg, a.lon_deg)
    return { az_deg: p.azDeg, el_deg: p.elDeg, decl_deg: p.declDeg, eot_min: p.eotMin, tst_min: p.tstMin }
  },
  refraction_deg: (a) => ({ v: refractionDeg(a.el_deg) }),
  illuminance_lx: (a) => ({ v: illuminanceLx(a.el_deg, a.cover, a.moon_lx) }),
  illum_band: (a) => ({ v: illumBand(a.el_deg) }),
  air_temp_c: (a) => ({ v: airTempC(a.t_mean, a.tst_min, a.cover) }),
  surface_temp_c: (a) => ({ v: surfaceTempC(a.t_air, a.el_deg, a.cover, a.wetness, SURFACE_CLASSES[a.cls]) }),
  sky_temp_c: (a) => ({ v: skyTempC(a.t_air, a.rh, a.cover, a.cloud_base_m) }),
  k_cross_of: (a) => ({ v: kCrossOf(a.el_now, a.el_before, a.el_after) }),
  a_weight_db: (a) => ({ v: aWeightDb(a.f_hz) }),
  level_dba: (a) => ({ v: levelDba(a.profile as AcousticProfile, a.el_deg, a.rain_eff_mmh) }),
  band_levels_dba: (a) => ({ v: Array.from(bandLevelsDba(a.profile as AcousticProfile, a.total)) }),
  water_vapour_gm3: (a) => ({ v: waterVapourGm3(a.rh, a.t_c) }),
  sigma_wv_per_m: (a) => ({ v: sigmaWvPerM(a.rho_v_gm3) }),
  sigma_lambda: (a) => {
    const d = derive(a.s, newDerived())
    return { v: sigmaLambda(d, a.lam_nm, kV2, a.rho_v_gm3), kim: kimFactor(d, a.lam_nm, kV2) }
  },
  parse_utc_ms: (a) => ({ v: parseUtcMs(a.s) }),
}
/* eslint-enable @typescript-eslint/no-explicit-any */

describe('D2 sky golden parity (python/awr/environment/sky)', () => {
  const fns = [...new Set(gold.cases.map((c) => c.fn))]
  for (const fn of fns) {
    it(fn, () => {
      for (const c of gold.cases.filter((x) => x.fn === fn)) {
        const got = DISPATCH[fn](c.args)
        for (const [k, want] of Object.entries(c.out)) {
          const g = got[k]
          if (want === null || typeof want === 'number' && Number.isInteger(want) && (fn === 'illum_band' || fn === 'parse_utc_ms')) {
            expect(g, `${fn} ${JSON.stringify(c.args)}`).toBe(want)
          } else if (Array.isArray(want)) {
            want.forEach((w: number, i: number) => expect(close(g[i], w), `${fn}[${i}] ${g[i]} vs ${w}`).toBe(true))
          } else if (k === 'az_deg') {
            const d = ((g - want + 540) % 360) - 180 // wrap at 0/360
            expect(Math.abs(d) <= 1e-7, `${fn} ${k} ${g} vs ${want}`).toBe(true)
          } else {
            // trig chains in V8 and CPython libm may differ in the last ulps: 1e-7 deg / relative 1e-9 elsewhere
            expect(close(g, want, fn === 'solar_position' ? 100 : 1), `${fn} ${k} ${JSON.stringify(c.args)} ${g} vs ${want}`).toBe(true)
          }
        }
      }
    })
  }
  it('acoustic bands sum to the total', () => {
    expect(totalDba(bandLevelsDba('urban', 57.5))).toBeCloseTo(57.5, 9)
  })
})

const SEC = 1e9

function wire(o: Partial<EnvKeyframeWire> = {}): EnvKeyframeWire {
  const v = Array.from(PRESETS_MODEL.presetVector('clear'))
  return {
    schema: 'awr.env.keyframe.v1', world_id: 'synthcity', version: 1, epoch: 1, seed: 1, t_ns: 0, t_apply_ns: 0,
    config: { wind: { level: 1, profile: { kind: 'log', z_ref_m: 10, z0_m: 0.5, d_m: 0, alpha: 0.25, adv_height_m: 40 }, library: null,
      turbulence: { model: 'box', n: 64, dx_m: 4, l_m: 30 }, gust: { model: 'cos1_front', max_active: 4 } },
    sun: { azimuth_deg: 150, elevation_deg: 50 }, weather_map: { n: 512, scale_m: 24000 }, presets_sha256: PRESETS_MODEL.sha256 },
    mode: 'step', t0_ns: 0, t1_ns: 0, from: v, to: v, via: [], to_preset: 'clear',
    anchors: { t_ns: 0, s_m: 0, d_enu_m: [0, 0, 0], fall_rain_m: 0, fall_snow_m: 0, wetness: 0, puddle: 0 }, events: [],
    vis: { streamlines: null, vmax_mps: 20 }, ...o,
  } as EnvKeyframeWire
}

describe('EnvStore sky (D2)', () => {
  const cal0 = Date.UTC(2026, 9, 5, 8, 30) // 16:30 Beijing
  const tNs = 120 * SEC
  const d2wire = (): EnvKeyframeWire => wire({
    t_ns: tNs, t_apply_ns: tNs, t0_ns: tNs, t1_ns: tNs,
    anchors: { t_ns: tNs, s_m: 0, d_enu_m: [0, 0, 0], fall_rain_m: 0, fall_snow_m: 0, wetness: 0, puddle: 0 },
    config: { ...wire().config, sun: { azimuth_deg: 252.5, elevation_deg: 18.2, mode: 'clock', illum_lx: 37480, band: 'day' } },
    calendar: { start_utc: '2026-10-05T08:30:00Z', tz: 'Asia/Shanghai', t_cal_unix_ns: String(BigInt(cal0) * 1000000n + BigInt(tNs)) },
    humidity_pct: 50, surface: { t_c: 24.5, emissivity: 0.93, k_cross: 1 }, acoustic_bg: { profile: 'rural', l_bg_dba: 40 },
  })

  it('D1 frames: fixed sun, no sky summary, full direct light', () => {
    const s = new EnvStore()
    s.ingest(wire(), 0)
    s.update(1, 10)
    expect(s.sky.mode).toBe('fixed')
    expect(s.sky.azDeg).toBe(150)
    expect(s.sky.elDeg).toBe(50)
    expect(s.sky.band).toBe(0)
    expect(Number.isNaN(s.sky.tCalUnixMs)).toBe(true)
    expect(buildSummary(s, 10, null).sky).toBeNull()
    expect(daylightK(50)).toBe(1)
  })

  it('calendar at tRender, keyframe sun without anchor, NOAA sun with anchor', () => {
    const s = new EnvStore()
    s.ingest(d2wire(), 0)
    s.update(1800, 10) // 30 min after t_sim = 0
    expect(s.sky.mode).toBe('clock')
    expect(s.sky.tCalUnixMs).toBe(cal0 + 1800_000)
    expect(s.sky.source).toBe('keyframe')
    expect(s.sky.elDeg).toBe(18.2)
    s.setGeoAnchor({ latDeg: 30, lonDeg: 120, yawOffsetDeg: 0 })
    s.update(1800, 20)
    const p = solarPosition(cal0 + 1800_000, 30, 120)
    expect(s.sky.source).toBe('noaa')
    expect(s.sky.elDeg).toBeCloseTo(p.elDeg, 9)
    expect(s.sky.azDeg).toBeCloseTo(p.azDeg, 9)
    expect(s.sky.illumLx).toBeCloseTo(illuminanceLx(p.elDeg, PRESETS_MODEL.presetVector('clear')[7]), 6)
    // two hours later the sun has set: band night, direct light off
    s.update(3 * 3600, 30)
    expect(s.sky.bandName).toBe('night')
    expect(daylightK(s.sky.elDeg)).toBe(0)
    const sum = buildSummary(s, 30, null).sky!
    expect(sum.band).toBe('night')
    expect(sum.localTime).toBe(formatLocal(cal0 + 3 * 3600_000, 'Asia/Shanghai'))
    expect(sum.localTime).toBe('2026-10-05 19:30')
    expect(sum.acoustic).toEqual({ profile: 'rural', lBgDba: 40 })
    expect(sum.surface).toEqual({ tC: 24.5, emissivity: 0.93, kCross: 1 })
    expect(sum.humidityPct).toBe(50)
  })

  it('update with D2 fields stays allocation-light (steady state, 20x replay steps)', () => {
    const s = new EnvStore()
    s.setGeoAnchor({ latDeg: 30, lonDeg: 120, yawOffsetDeg: 0 })
    s.ingest(d2wire(), 0)
    for (let i = 1; i < 6000; i++) s.update(120 + i * 0.033 * 20, i * 33) // warm up to optimised code (NOAA chain)
    const g = globalThis as { gc?: () => void }
    const before = process.memoryUsage().heapUsed
    for (let i = 6000; i < 8000; i++) s.update(120 + i * 0.033 * 20, i * 33)
    g.gc?.()
    expect(process.memoryUsage().heapUsed - before).toBeLessThan(4 * 1024 * 1024)
    expect(s.sky.source).toBe('noaa')
  })

  it('calendar parsing mirrors the server rules', () => {
    expect(parseUtcMs('2026-10-05T23:00:00+08:00')).toBe(Date.UTC(2026, 9, 5, 15))
    expect(parseUtcMs('2026-02-30T00:00:00Z')).toBeNull()
    expect(parseUtcMs('1900-01-01T00:00:00Z')).toBeNull()
    expect(formatLocal(Date.UTC(2026, 9, 5, 15), 'Not/AZone')).toBe('2026-10-05 15:00Z')
  })
})
